import Foundation
import Testing
@testable import UnlispaceKit

/// Context and credentials are generated by the isolated local Worker harness, never production.
@Suite @MainActor struct DesktopWorkerTests {
    private struct Context: Decodable {
        var api: URL
        var callbackURL: URL
        var state: String
        var verifier: String
        var socket: String
    }

    @Test(.enabled(if: ProcessInfo.processInfo.environment["ULS_DESKTOP_TEST_CONTEXT"] != nil && ProcessInfo.processInfo.environment["ULS_TEST_KEYCHAIN"] == "1"))
    func browserCodeExchangesAndHandsSessionToRealDaemon() async throws {
        let path = try #require(ProcessInfo.processInfo.environment["ULS_DESKTOP_TEST_CONTEXT"])
        let context = try JSONDecoder().decode(Context.self, from: Data(contentsOf: URL(fileURLWithPath: path)))
        try #require(context.api.scheme == "http" && context.api.host == "127.0.0.1")
        try #require(context.socket.hasPrefix("/private/tmp/unlispace-e2e.") || context.socket.hasPrefix("/tmp/unlispace-e2e."))
        let auth = DesktopAuth()
        // A forged callback must be rejected before consuming the one-time code.
        await #expect(throws: AuthError.stateMismatch) {
            try await auth.exchange(callbackURL: context.callbackURL, api: context.api, expectedState: "wrong-state", verifier: context.verifier)
        }
        let session = try await auth.exchange(callbackURL: context.callbackURL, api: context.api, expectedState: context.state, verifier: context.verifier)
        #expect(!session.accessToken.isEmpty && !session.refreshToken.isEmpty)
        let client = UnixSocketDaemonClient(socketPath: context.socket)
        try await client.connect()
        do {
            // Exercise deferred storage only in an isolated test Keychain service.
            let keychain = Keychain(service: "com.unlispace.desktop-worker-tests.\(UUID().uuidString)")
            let handoff = SessionHandoff(keychain: keychain)
            defer { handoff.discardPending() }
            #expect(try await handoff.deliver(session, api: context.api, to: nil) == .deferred)
            #expect(handoff.hasPending)
            #expect(try await handoff.retryPending(to: client) == .delivered(AuthUser(id: session.user.id, email: session.user.email)))
            #expect(!handoff.hasPending)
            #expect(try await client.authStatus().signedIn)
            #expect(!(try await client.listDrives()).isEmpty)
            // The same browser code must be unusable after a successful exchange.
            await #expect(throws: AuthError.exchangeFailed(400)) {
                try await auth.exchange(callbackURL: context.callbackURL, api: context.api, expectedState: context.state, verifier: context.verifier)
            }
            try await client.authSignOut()
            #expect(try await client.authStatus().signedIn == false)
        } catch {
            await client.disconnect()
            throw error
        }
        await client.disconnect()
    }
}
